export function ReviewEmbed({
  sourceName = "{{sourceName}}",
  rating = {{rating}},
  reviewCount = {{reviewCount}},
  layout = "{{layout}}",
  accent = "{{accent}}",
}) {
  const expanded = layout === "expanded";
  return (
    <div style={{ maxWidth: 320, padding: "18px 20px", borderRadius: 12, border: "1.5px solid #24143026",
      background: "#FAF7F2", color: "#241430", fontFamily: "system-ui, sans-serif" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
        <span style={{ fontWeight: 700, fontSize: 14 }}>{sourceName}</span>
        <span style={{ position: "relative", display: "inline-block", fontSize: 16, lineHeight: 1, letterSpacing: 2 }}
          role="img" aria-label={`Rated ${rating} out of 5 stars`}>
          <span style={{ color: "#24143026" }} aria-hidden="true">★★★★★</span>
          <span style={{ position: "absolute", inset: 0, width: `calc(${rating} / 5 * 100%)`, overflow: "hidden",
            whiteSpace: "nowrap", color: accent }} aria-hidden="true">★★★★★</span>
        </span>
        <span style={{ fontSize: 13, color: "#241430aa" }}>{rating} / 5</span>
      </div>
      <p style={{ margin: "6px 0 0", fontSize: 13, color: "#241430aa" }}>Based on {reviewCount} reviews</p>
      {expanded && (
        <blockquote style={{ margin: "14px 0 0", paddingTop: 12, borderTop: "1px solid #24143020", fontSize: 14, fontStyle: "italic" }}>
          “Support answered within the hour and actually fixed the problem. Would recommend without hesitation.”
          <cite style={{ display: "block", marginTop: 6, fontSize: 12, fontStyle: "normal", color: "#241430aa" }}>— Priya N.</cite>
        </blockquote>
      )}
    </div>
  );
}
